// Both ends read ~/.a-tether/settings.json. On one machine they share the file,
// so the token generated by the server works for the Pi plugin without setup.
import { randomBytes } from "node:crypto";
import { chmodSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from "node:fs";
import { isIPv4, isIPv6 } from "node:net";
import { homedir } from "node:os";
import { dirname, join } from "node:path";

export const displayPath = "~/.a-tether/settings.json";
export const settingsPath = () => join(homedir(), ".a-tether", "settings.json");

export type Settings = {
  token?: string;
  server: {host: string; port: number; claude: string; allowUsageCredits: boolean; maxSessions: number;
    heartbeatInterval: number; heartbeatTimeout: number};
  client: {url: string; pi?: string};
};

export class SettingsError extends Error {}

type Json = Record<string, unknown>;
const isObject = (value: unknown): value is Json => typeof value === "object" && value !== null && !Array.isArray(value);

// Printable ASCII only: the token travels in an HTTP header.
export const validToken = (value: unknown): value is string => typeof value === "string" && /^[\x21-\x7e]{32,}$/.test(value);
export const generateToken = () => randomBytes(32).toString("hex");
export const loginCommand = (token: string) => "npx -y @a-tether/pi login " + token;
export function isLoopback(host: string) {
  const h = host.toLowerCase();
  if (h === "localhost") return true;
  if (isIPv4(h)) return h.startsWith("127.");
  return isIPv6(h) && (/^(0{1,4}:){7}0{0,3}1$/.test(h) || h === "::1" || /^::ffff:127\./.test(h));
}

function readRaw(file: string): Json | undefined {
  let text: string;
  try { text = readFileSync(file, "utf8"); }
  catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return undefined;
    throw new SettingsError(`无法读取 ${file}：${(error as Error).message}`);
  }
  let data: unknown;
  try { data = JSON.parse(text); }
  catch { throw new SettingsError(`${file} 不是合法的 JSON，请修正或删除后重试。`); }
  if (!isObject(data)) throw new SettingsError(`${file} 的内容必须是一个 JSON 对象。`);
  return data;
}

export function loadSettings(file = settingsPath()): Settings {
  const raw = readRaw(file) ?? {};
  const fail = (field: string, rule: string): never => { throw new SettingsError(`${file} 中的 ${field} ${rule}。`); };
  const section = (name: string): Json => {
    const value = raw[name];
    if (value === undefined) return {};
    return isObject(value) ? value : fail(name, "必须是对象");
  };
  const text = (obj: Json, field: string) => {
    const value = obj[field.split(".")[1]];
    if (value === undefined) return undefined;
    return typeof value === "string" && value.trim() ? value : fail(field, "必须是非空字符串");
  };
  const server = section("server");
  const client = section("client");
  if (raw.token !== undefined && !validToken(raw.token)) fail("token", "必须是至少 32 个字符的字符串，只含字母、数字和符号，不含空白");
  const port = server.port ?? 7310;
  if (typeof port !== "number" || !Number.isInteger(port) || port < 1 || port > 65535) fail("server.port", "必须是 1–65535 的整数");
  const allowUsageCredits = server.allowUsageCredits ?? false;
  if (typeof allowUsageCredits !== "boolean") fail("server.allowUsageCredits", "必须是 true 或 false");
  const maxSessions = server.maxSessions ?? 16;
  if (typeof maxSessions !== "number" || !Number.isInteger(maxSessions) || maxSessions < 0 || maxSessions > 256) fail("server.maxSessions", "必须是 0–256 的整数");
  const heartbeatInterval = server.heartbeatInterval ?? 10;
  if (typeof heartbeatInterval !== "number" || !Number.isInteger(heartbeatInterval) || heartbeatInterval < 1 || heartbeatInterval > 600) fail("server.heartbeatInterval", "必须是 1–600 的整数（秒）");
  const heartbeatTimeout = server.heartbeatTimeout ?? Math.max(30, 3 * (heartbeatInterval as number));
  // One late beat must not end a request, so the timeout spans at least two intervals.
  if (typeof heartbeatTimeout !== "number" || !Number.isInteger(heartbeatTimeout) || heartbeatTimeout > 3600 ||
      heartbeatTimeout < 2 * (heartbeatInterval as number)) fail("server.heartbeatTimeout", "必须是整数（秒），不小于 server.heartbeatInterval 的 2 倍，不大于 3600");
  // Without client.url, Pi on the same machine follows server.port.
  const url = text(client, "client.url") ?? "http://127.0.0.1:" + port;
  let origin = "";
  try {
    const parsed = new URL(url);
    if (parsed.protocol === "http:" && parsed.hostname && !parsed.username && !parsed.password &&
        parsed.pathname === "/" && !parsed.search && !parsed.hash) origin = parsed.origin;
  } catch {}
  if (!origin) fail("client.url", "必须形如 http://127.0.0.1:7310（不带路径和账号密码）");
  return {
    token: raw.token as string | undefined,
    server: {host: text(server, "server.host") ?? "127.0.0.1", port: port as number,
      claude: text(server, "server.claude") ?? "claude", allowUsageCredits: allowUsageCredits as boolean,
      maxSessions: maxSessions as number, heartbeatInterval: heartbeatInterval as number, heartbeatTimeout: heartbeatTimeout as number},
    client: {url: origin, pi: text(client, "client.pi")},
  };
}

// Replaces only the token and keeps every other field. Writes a private temp
// file and renames it, so an interrupted write never leaves half a file.
export function saveToken(token: string, file = settingsPath()) {
  if (!validToken(token)) throw new SettingsError("令牌必须是至少 32 个字符的字符串，只含字母、数字和符号，不含空白。请完整复制 C 端打印的令牌。");
  const data = {...readRaw(file), token};
  mkdirSync(dirname(file), {recursive: true, mode: 0o700});
  chmodSync(dirname(file), 0o700); // mode above only applies when the directory is new
  const temp = `${file}.${process.pid}.tmp`;
  try {
    writeFileSync(temp, JSON.stringify(data, null, 2) + "\n", {mode: 0o600});
    chmodSync(temp, 0o600);
    renameSync(temp, file);
  } catch (error) {
    rmSync(temp, {force: true});
    throw error;
  }
}
